mapper.select:
SELECT SUM(IFNULL(ods.bid_amount,0)) AS totalAmount, COUNT(DISTINCT pt.id) AS quantity, pt.`bidding_type` AS projectType FROM project_tendering pt LEFT JOIN bidding_rounds br ON br.project_id = pt.id AND br.round = (SELECT MAX(ROUND) FROM bidding_rounds WHERE project_id = pt.id) LEFT JOIN project_tendering_supplier pts ON pts.project_tendering_id = pt.id AND pts.bid_status = 1 LEFT JOIN offer_rounds os ON os.supplier_id = pts.`id` AND os.project_tendering_id = pt.`id` AND os.`offer_round` = br.`round` LEFT JOIN offer_round_detail ods on ods.offer_id = os.id AND ods.is_follow = 1 and ods.project_id = pt.id
AND pt.UUID = #{uuid}
AND pt.project_type = #{projectType}
AND date(pt.create_time) >= date(#{startDate})
AND date(pt.create_time) <= date(#{endDate})
GROUP BY pt.`bidding_type`
